import { ValidationError } from '../errors/DomainErrors';

/** A non-negative amount of money held in minor units (cents) to avoid floating-point drift. */
export class Money {
  private constructor(readonly cents: number) {}

  static ofCents(cents: number): Money {
    if (!Number.isInteger(cents) || cents < 0) {
      throw new ValidationError(`Money must be a non-negative integer number of cents, got ${String(cents)}`);
    }
    return new Money(cents);
  }

  static zero(): Money {
    return new Money(0);
  }

  add(other: Money): Money {
    return new Money(this.cents + other.cents);
  }

  multiply(factor: number): Money {
    return Money.ofCents(this.cents * factor);
  }
}

=====SOURCE-END=====

